-- 20260718_cbam_benchmarks.sql
-- IR (EU) 2025/2620, Annex point 5.3 — CBAM benchmark values (Iron & Steel only).
-- Generated from docs/cbam-2620-benchmarks-raw.csv (verbatim OJ extraction).
--
-- Column A (BM*_g) feeds Equation 2  — the ACTUAL-data path (Annex §3.1).
-- Column B (BM_g)  feeds Equation 6  — the DEFAULT-values path (Annex §4).
-- They diverge by up to ~30x. They are NEVER merged; there is no field called 'benchmark'.
--
-- route_indicator NULL = the value applies to all production routes.
-- period_band     NULL = the value applies to all production years.
--   1 = production years 2026-27, 2 = production years 2028-30.
-- Route legend (§5.3): C BF/BOF carbon, D DRI/EAF carbon, E scrap/EAF carbon,
--   F BF/BOF low alloy, G DRI/EAF low alloy, H scrap/EAF low alloy, J high alloy EAF.
--   There is no indicator (I) in the source — the sequence runs (H) -> (J).
--
-- Key: the natural key (cn_code, bm_column, route_indicator, period_band) contains
-- nullable columns, so it cannot be a PRIMARY KEY (a PK forces NOT NULL and would
-- destroy the 'applies to all' NULL sentinel). Postgres 17 is in use, so the natural
-- key is enforced with UNIQUE NULLS NOT DISTINCT — which, unlike a default UNIQUE,
-- does treat two NULLs as equal and therefore does block duplicates.
-- 0,000 Column A values are explicit zeros in the OJ, not missing data — not coerced to NULL.

create table if not exists public.cbam_benchmarks (
  id              bigint generated always as identity primary key,
  cn_code         text    not null,
  bm_column       text    not null check (bm_column in ('A','B')),
  route_indicator text    check (route_indicator in ('C','D','E','F','G','H','J')),
  period_band     int     check (period_band in (1,2)),
  value           numeric not null,
  source_cell     text    not null,
  constraint cbam_benchmarks_key
    unique nulls not distinct (cn_code, bm_column, route_indicator, period_band)
);

create index if not exists cbam_benchmarks_lookup
  on public.cbam_benchmarks (cn_code, bm_column);

