grant select on public.cbam_benchmarks to anon, authenticated;
alter table public.cbam_benchmarks enable row level security;
do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='cbam_benchmarks' and policyname='cbam_benchmarks_read') then
    create policy cbam_benchmarks_read on public.cbam_benchmarks for select to anon, authenticated using (true);
  end if;
end $$;
